class Solution {
    public int arrangeCoins(int n) {
        int left = 1;
        int right = n;
        int answer = 0;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            long need = (long) mid * (mid + 1) / 2;
            if (need <= n) {
                answer = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return answer;
    }
}

class Solution {
    public int arrangeCoins(int n) {
        int result = (int) ((Math.sqrt(1.0 + 8.0 * n) - 1) / 2);
        while ((long) (result + 1) * (result + 2) / 2 <= n) {
            result++;
        }
        while ((long) result * (result + 1) / 2 > n) {
            result--;
        }
        return result;
    }
}

class Solution {
    public int arrangeCoins(int n) {
        long target = 8L * n + 1;
        long left = 1;
        long right = target;
        long root = 1;
        while (left <= right) {
            long mid = left + (right - left) / 2;
            if (mid <= target / mid) {
                root = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return (int) ((root - 1) / 2);
    }
}

class Solution {
    public int arrangeCoins(int n) {
        long target = 8L * n + 1;
        long x = target;
        while (x > target / x) {
            x = (x + target / x) / 2;
        }
        return (int) ((x - 1) / 2);
    }
}

class Solution {
    public int arrangeCoins(int n) {
        int rows = 0;
        int next = 1;
        int remaining = n;
        while (remaining >= next) {
            remaining -= next;
            rows++;
            next++;
        }
        return rows;
    }
}
